{
  "justification": "Cost of living and the economy dominate salience while immigration is a close second; respondents are slightly left of center economically but notably more authoritarian on the derived scale. Slight Euroscepticism and immigration salience elevate loyalty/authority themes, while health and environment keep care present, yielding a balanced but authority- and equality-leaning profile.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "Issue salience: health 7.0%, environment 6.1%, and cost-of-living impacts on well-being 19.7%.",
      "weight": 0.18
    },
    {
      "foundation": "equality",
      "basis": "Cost of living 19.7% plus redistribution placement mean 4.68 and mentions of poverty/inequality.",
      "weight": 0.22
    },
    {
      "foundation": "proportionality",
      "basis": "Economy-general 13.7%, taxation 0.5%, inflation 1.7%, and centrist left-right mean 4.74.",
      "weight": 0.17
    },
    {
      "foundation": "authority",
      "basis": "Derived authority-liberty 6.2 (more authoritarian) and salience of immigration 17.0%, crime 2.4%, defence 1.3%.",
      "weight": 0.22
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration 17.0%, slightly lower EU integration support 4.73, and war/defence salience 2.0%/1.3%.",
      "weight": 0.15
    },
    {
      "foundation": "sanctity",
      "basis": "Low but present morals 0.3% and gender/sexuality/family 0.1%, with some purity-tinged environmental concern 6.1%.",
      "weight": 0.06
    }
  ]
}
